// Provide storage for the position output; must be a valid lvalue reference
size_t invalidPos = 0;

// Call the detailed overload that returns the first invalid byte position
bool ok_with_pos = solidity::util::validateUTF8(input, invalidPos);

// Call the convenience overload and ensure it is consistent with the detailed one
bool ok_simple = solidity::util::validateUTF8(input);
FUZZ_ASSERT(ok_simple == ok_with_pos, "validateUTF8 overloads returned inconsistent results");

// If invalid, position must be within [0, input.size()-1] when input is non-empty
if (!ok_with_pos) {
    if (!input.empty()) {
        FUZZ_ASSERT(invalidPos < input.size(), "Invalid position must be within input bounds for non-empty input");
