import random
from typing import List

# This generator produces byte sequences targeting UTF-8 validation logic.
# It aims to create mostly valid UTF-8 strings of different structures as well as
# controlled invalid cases. The output is a bytes object suitable for feeding
# FUZZ_PARAM_STR / FUZZ_PARAM_FILENAME data files.

MAX_LEN = 4096

# Helpers to build valid UTF-8

def _enc_scalar(v: int) -> bytes:
    """Encode a Unicode scalar value (0..0x10FFFF excluding surrogates) into UTF-8 bytes."""
    assert 0 <= v <= 0x10FFFF and not (0xD800 <= v <= 0xDFFF)
    if v <= 0x7F:
        return bytes([v])
    if v <= 0x7FF:
        return bytes([0xC0 | (v >> 6), 0x80 | (v & 0x3F)])
    if v <= 0xFFFF:
        return bytes([0xE0 | (v >> 12), 0x80 | ((v >> 6) & 0x3F), 0x80 | (v & 0x3F)])
    return bytes([
        0xF0 | (v >> 18),
        0x80 | ((v >> 12) & 0x3F),
        0x80 | ((v >> 6) & 0x3F),
        0x80 | (v & 0x3F),
    ])

# Invalid constructors

def _overlong_ascii(rng: random.Random) -> bytes:
    # Overlong encodings for ASCII 0..127 using 2-4 bytes
    v = rng.randrange(0, 0x80)
    mode = rng.choice([2, 3, 4])
    if mode == 2:
        b2 = 0x80 | (v & 0x3F)
        b1 = 0xC0 | ((v >> 6) & 0x01)  # yields 0xC0 or 0xC1
        return bytes([b1, b2])
    if mode == 3:
        b1 = 0xE0
        b2 = 0x80
        b3 = 0x80 | v
        return bytes([b1, b2, b3])
    b1 = 0xF0
    return bytes([b1, 0x80, 0x80, 0x80 | v])

def _bad_continuation(rng: random.Random) -> bytes:
    # Start byte requiring continuations but provide wrong continuation patterns
    lead = rng.choice([
        0xC2, 0xDF,  # valid 2-byte leads
        0xE0, 0xEF,  # valid 3-byte leads
        0xF0, 0xF4   # valid 4-byte leads within Unicode range
    ])
    need = 1 if lead <= 0xDF else (2 if lead <= 0xEF else 3)
    out = [lead]
    for _ in range(need):
        # mix invalid continuation bytes
        if rng.random() < 0.5:
            out.append(rng.randrange(0x00, 0x80))  # not 10xxxxxx
        else:
            out.append(rng.randrange(0xC0, 0xFF))  # also not 10xxxxxx
    return bytes(out)

def _truncated(rng: random.Random) -> bytes:
    # Start a multi-byte sequence and then cut it short
    lead = rng.choice([0xC2, 0xE0, 0xF0])
    need = 1 if lead == 0xC2 else (2 if lead == 0xE0 else 3)
    have = rng.randrange(0, need)  # strictly less than need
    out = [lead]
    for _ in range(have):
        out.append(0x80 | rng.randrange(0, 0x40))
    return bytes(out)

def _surrogate_code_point(rng: random.Random) -> bytes:
    # Encode UTF-16 surrogate halves (invalid in UTF-8)
    cp = rng.randrange(0xD800, 0xE000)
    b1 = 0xE0 | (cp >> 12)
    b2 = 0x80 | ((cp >> 6) & 0x3F)
    b3 = 0x80 | (cp & 0x3F)
    return bytes([b1, b2, b3])

def _out_of_range_code_point(rng: random.Random) -> bytes:
    # 4-byte sequence claiming a value > U+10FFFF
    if rng.random() < 0.5:
        b1 = 0xF4
        b2 = 0x90 | rng.randrange(0x10, 0x20)
        b3 = 0x80 | rng.randrange(0, 0x40)
        b4 = 0x80 | rng.randrange(0, 0x40)
        return bytes([b1, b2 & 0xBF, b3, b4])
    else:
        b1 = rng.randrange(0xF5, 0xF8)
        return bytes([b1, 0x80 | rng.randrange(0, 0x40), 0x80 | rng.randrange(0, 0x40), 0x80 | rng.randrange(0, 0x40)])

# Random valid scalar generation

def _rand_scalar(rng: random.Random) -> int:
    choices = [
        (0x0000, 0x007F, 4),   # ASCII
        (0x0080, 0x07FF, 3),   # 2-byte
        (0x0800, 0xD7FF, 5),   # 3-byte before surrogates
        (0xE000, 0xFFFF, 4),   # 3-byte after surrogates
        (0x10000, 0x10FFFF, 2) # 4-byte
    ]
    total_w = sum(w for _, _, w in choices)
    pick = rng.randrange(total_w)
    acc = 0
    for lo, hi, w in choices:
        if pick < acc + w:
            return rng.randrange(lo, hi + 1)
        acc += w
    return rng.randrange(0, 0x10FFFF + 1)


def _valid_string(rng: random.Random, target_len: int) -> bytes:
    # Ensure non-negative
    if target_len <= 0:
        return b""
    out = bytearray()
    while len(out) < target_len:
        roll = rng.random()
        if roll < 0.15:
            cp = rng.choice([0x0000, 0x0009, 0x000A, 0x000D, 0x0020, 0x007F])
        elif roll < 0.25:
            cp = rng.choice([0x00A9, 0x03A9, 0x20AC, 0x2028, 0x2029])
        elif roll < 0.35:
            cp = rng.randrange(0x80, 0x7FF)
        elif roll < 0.6:
            cp = rng.randrange(0x0800, 0xD7FF)
        elif roll < 0.85:
            cp = rng.randrange(0xE000, 0xFFFF)
        else:
            cp = rng.randrange(0x10000, 0x10FFFF)
        # Skip surrogate range guard (shouldn't be selected but be safe)
        if 0xD800 <= cp <= 0xDFFF:
            continue
        enc = _enc_scalar(cp)
        if len(out) + len(enc) > target_len:
            break
        out.extend(enc)
        # Avoid infinite loop if a single codepoint exceeds remaining space
        if target_len - len(out) < 1:
            break
    # If still empty, add a single ASCII to ensure progress up to target_len
    if not out and target_len > 0:
        out.extend(_enc_scalar(0x41))  # 'A'
    return bytes(out[:target_len])


def _invalid_fragment(rng: random.Random) -> bytes:
    maker = rng.choice([
        _overlong_ascii,
        _bad_continuation,
        _truncated,
        _surrogate_code_point,
        _out_of_range_code_point,
    ])
    return maker(rng)


def _mix_cases(rng: random.Random, max_total: int) -> bytes:
    max_total = max(1, max_total)
    parts: List[bytes] = []
    if rng.random() < 0.8:
        prefix_len = rng.randrange(0, max(1, max_total // 2))
        parts.append(_valid_string(rng, prefix_len))
    parts.append(_invalid_fragment(rng))
    if rng.random() < 0.7:
        remain = max_total - sum(len(p) for p in parts)
        if remain > 0:
            parts.append(_valid_string(rng, rng.randrange(0, remain + 1)))
    data = b"".join(parts)
    return data[:max_total]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    scenario = rng.choices(
        population=[
            "empty",
            "ascii",
            "valid_mixed",
            "valid_long",
            "invalid_first_byte",
            "invalid_mixed",
            "truncated_tail",
            "overlong_only",
            "boundary_values",
        ],
        weights=[2, 6, 10, 4, 5, 10, 5, 4, 4],
        k=1,
    )[0]

    # Pick a maximum payload length; ensure at least 1 to avoid empty range errors
    max_len = max(1, rng.randrange(1, min(1024, MAX_LEN) + 1))

    if scenario == "empty":
        return b""

    if scenario == "ascii":
        length = rng.randrange(1, max_len + 1)
        buf = bytearray()
        for _ in range(length):
            if rng.random() < 0.1:
                buf.append(rng.choice([0x00, 0x09, 0x0A, 0x0D]))
            else:
                buf.append(rng.randrange(0x20, 0x7F))
        return bytes(buf)

    if scenario == "valid_mixed":
        length = rng.randrange(1, max_len + 1)
        return _valid_string(rng, length)

    if scenario == "valid_long":
        lo = max(1, max_len // 2)
        hi = max(lo, max_len)
        length = rng.randrange(lo, hi + 1)
        return _valid_string(rng, length)

    if scenario == "invalid_first_byte":
        if max_len == 1:
            # Only room for the invalid byte
            return bytes([rng.randrange(0x80, 0xC0)])
        first = rng.randrange(0x80, 0xC0)  # stray continuation
        tail = _valid_string(rng, rng.randrange(0, max_len))
        return bytes([first]) + tail[: max_len - 1]

    if scenario == "invalid_mixed":
        return _mix_cases(rng, max_len)

    if scenario == "truncated_tail":
        prefix_len = rng.randrange(0, max(1, max_len // 2))
        prefix = _valid_string(rng, prefix_len)
        trunc = _truncated(rng)
        remain = max(0, max_len - len(prefix) - len(trunc))
        suffix = b""
        if remain > 0 and rng.random() < 0.3:
            suffix = _valid_string(rng, rng.randrange(1, remain + 1))
        return (prefix + trunc + suffix)[:max_len]

    if scenario == "overlong_only":
        data = bytearray()
        while len(data) < max_len:
            frag = _overlong_ascii(rng)
            if len(data) + len(frag) > max_len:
                break
            data.extend(frag)
            if rng.random() < 0.3:
                pad_len = rng.randrange(0, min(8, max_len - len(data)) + 1)
                data.extend(_valid_string(rng, pad_len))
        if not data:
            # Ensure non-empty when scenario expects data
            data.extend(_overlong_ascii(rng))
        return bytes(data[:max_len])

    if scenario == "boundary_values":
        cps = [
            0x0000, 0x007F, 0x0080, 0x07FF, 0x0800, 0xFFFF, 0x10000, 0x10FFFF,
            0xD7FF, 0xE000
        ]
        out = bytearray()
        for cp in cps:
            if 0xD800 <= cp <= 0xDFFF:
                continue
            out.extend(_enc_scalar(cp))
        out.extend(_surrogate_code_point(rng))
        out.extend(_out_of_range_code_point(rng))
        if len(out) < max_len:
            out.extend(_valid_string(rng, max_len - len(out)))
        return bytes(out[:max_len])

    # Fallback
    return _valid_string(rng, rng.randrange(1, max_len + 1))
